-- Batch 2 occupation expansion (2026-07-23): 32 additions deepening coverage
-- for ambitious students: space/aerospace (propulsion, GNC, flight test,
-- satellite systems, mission ops, astronaut), missing medical specialties
-- (neurosurgery, plastics, ophthalmology, OB/GYN, CRNA, optometry, MD-PhD),
-- research/academia (neuroscience, quantum, math, climate, national labs,
-- policy), tech (chip design, AI safety, engineering management, quant dev,
-- embedded), government prestige tracks (air traffic control, FBI,
-- intelligence), corporate (strategy, sales engineering), and creative
-- outliers (industrial design, fashion, screenwriting).
--
-- BLS fields reuse programmatically verified batch-1 numbers where the SOC
-- code already existed in the catalog; SOC codes NEW in this batch carry
-- best-effort values from the same 2024-34 Employment Projections cycle,
-- marked bls_match_confidence 'approximate' with a note, and are flagged for
-- founder verification against Table 1.2. Additive only: no existing rows
-- are touched. See scripts/occupations-batch2-data.mjs.

insert into occupations (
  title, description, median_salary, growth_pct, education_level, top_skills, trait_profile, data_as_of,
  soc_code, bls_change_pct_2024_34, bls_median_wage_2024, bls_annual_openings_thousands, bls_match_confidence, bls_match_note,
  how_to_break_in, typical_progression, skills_to_build_first, common_misconceptions, interview_focus
)
values
  ('Rocket Propulsion Engineer', 'Designs, models, and test-fires the engines that put rockets in orbit, from turbopumps to combustion chambers.', 135000, 6, 'Bachelor''s degree (aerospace/mechanical)', ARRAY['Thermodynamics & fluid dynamics', 'Propulsion system design', 'Test campaign execution', 'CAD & simulation (ANSYS/CFD)']::text[], '{"quadrant_a":0.92,"quadrant_b":0.55,"quadrant_c":0.15,"quadrant_d":0.35,"pace_preference":0.55,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '17-2011', 6.1, 134830, 4.5, 'close', 'Mapped to Aerospace Engineers (17-2011), verified batch-1 numbers; propulsion is a specialization within that code.', 'SpaceX, Blue Origin, Rocket Lab, and NASA contractors recruit heavily from hands-on rocketry: collegiate liquid-fuel teams, NASA Student Launch, and propulsion-focused internships matter more than GPA alone. An aerospace or mechanical degree with strong thermo/fluids coursework is the baseline; a test-stand video of something you built is what gets the interview.', 'Propulsion Engineer I on a component (injector, valve, turbopump) for 2-3 years, then owning a subsystem, then Responsible Engineer for an engine program, then Senior/Staff or engineering management around year 8-12.', ARRAY['Thermodynamics and compressible flow', 'CAD (SolidWorks/NX) and CFD basics', 'Hands-on build experience (rocketry club, machine shop)', 'Python or MATLAB for engineering analysis', 'Test data reduction']::text[], 'People picture designing whole rockets; you own one component for years, and most of the job is analysis, testing, and failure investigation rather than clean-sheet design. Launch days are rare punctuation on months of test-stand work.', 'Deep fundamentals under pressure: derive the rocket equation, walk through how a turbopump works, explain a combustion instability. SpaceX-style panels probe what you personally built, every ''we'' answer gets converted to ''what did YOU do.'''),
  ('Spacecraft GNC Engineer', 'Builds the guidance, navigation, and control algorithms that keep rockets pointed and spacecraft where they belong.', 140000, 6, 'Bachelor''s/Master''s (aero, EE, or controls)', ARRAY['Control theory', 'Orbital mechanics', 'Kalman filtering & estimation', 'MATLAB/Simulink & C++']::text[], '{"quadrant_a":0.94,"quadrant_b":0.5,"quadrant_c":0.12,"quadrant_d":0.3,"pace_preference":0.5,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '17-2011', 6.1, 134830, 4.5, 'close', 'Mapped to Aerospace Engineers (17-2011), verified batch-1 numbers; GNC is a specialization within that code.', 'The most math-heavy corner of aerospace: controls, estimation, and orbital mechanics coursework plus a project that closes a real control loop (drone autopilot, CubeSat ADCS, rocket TVC) is the entry ticket. Master''s degrees are common but a strong undergrad with flight software projects breaks in at launch startups.', 'GNC Engineer on simulation or a single mode (ascent, landing, docking) for 2-4 years, then algorithm ownership, then GNC lead for a vehicle, then chief engineer or autonomy architect roles.', ARRAY['Classical and state-space control theory', 'Linear algebra and probability (Kalman filters)', 'MATLAB/Simulink plus C++', 'Orbital mechanics fundamentals', 'A closed-loop hardware project (drone or rocket)']::text[], 'It sounds like flying spacecraft by joystick; it''s writing and proving algorithms that fly them, and the bar for ''proving'' is simulation campaigns and reviews, not vibes. Much of the work is estimation (knowing where you are), not control.', 'Expect whiteboard controls problems (design a PID, explain gain margins), orbital mechanics puzzles (how do you catch up to a target ahead of you in the same orbit), and probing of any flight project on your resume down to the block-diagram level.'),
  ('Flight Test Engineer', 'Plans and runs the test campaigns that prove new aircraft and rockets actually work, instrumenting vehicles and calling the shots in real time.', 120000, 6, 'Bachelor''s degree (aero/mechanical/EE)', ARRAY['Test planning & safety review', 'Instrumentation & telemetry', 'Real-time decision making', 'Data analysis']::text[], '{"quadrant_a":0.6,"quadrant_b":0.9,"quadrant_c":0.2,"quadrant_d":0.3,"pace_preference":0.75,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '17-2011', 6.1, 134830, 4.5, 'approximate', 'Mapped to Aerospace Engineers (17-2011), verified batch-1 numbers; flight test spans several engineering codes.', 'Flight test hires people who have broken things safely: UAS test experience, experimental aircraft clubs, or instrumentation work on any test stand. Defense primes, the FAA path, and startups (where one FTE covers everything) are the three main doors; a private pilot''s license is a genuine differentiator.', 'Instrumentation or data engineer on a test team, then discipline engineer writing test cards, then Test Director running control rooms, then chief of flight test. The National Test Pilot School or USAF TPS route leads to flight test leadership on major programs.', ARRAY['Instrumentation and data acquisition', 'Test planning and hazard analysis', 'Python/MATLAB for flight data reduction', 'Telemetry systems basics', 'Clear real-time communication']::text[], 'It is not a desk-free adrenaline job: for every test point flown there are days of planning, safety review, and data review. The discipline is knowing when NOT to fly.', 'Scenario judgment dominates: a parameter drifts out of limits mid-test, what do you do. They probe your personal test experience, how you handle a test that destroys hardware, and whether you communicate crisply under time pressure.'),
  ('Satellite Systems Engineer', 'Owns how a satellite''s power, thermal, comms, and payload fit together, from requirements through launch and on-orbit checkout.', 130000, 6, 'Bachelor''s/Master''s (aero, EE, systems)', ARRAY['Systems engineering & requirements', 'Spacecraft subsystems', 'Integration & test', 'Trade studies']::text[], '{"quadrant_a":0.6,"quadrant_b":0.88,"quadrant_c":0.25,"quadrant_d":0.25,"pace_preference":0.5,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '17-2011', 6.1, 134830, 4.5, 'close', 'Mapped to Aerospace Engineers (17-2011), verified batch-1 numbers; satellite systems work sits squarely in this code.', 'University CubeSat programs are the single best pipeline: shipping even a 1U satellite touches every subsystem a professional program does. Starlink-scale constellations, defense primes, and NewSpace startups all hire systems engineers earlier in their careers than legacy aerospace ever did.', 'Subsystem engineer (power, thermal, comms) for 2-3 years, then satellite systems engineer across subsystems, then mission systems lead, then program chief engineer.', ARRAY['Spacecraft subsystem fundamentals', 'Requirements writing and verification', 'MATLAB/Python analysis', 'Integration and test discipline', 'A CubeSat or high-altitude balloon project']::text[], 'Systems engineering sounds like paperwork; on a real program the systems engineer is the person who actually understands the whole vehicle and arbitrates every cross-subsystem fight. It is a technical leadership track, not documentation.', 'Expect trade-study questions (solar array sizing vs battery mass), failure-chain reasoning (the satellite goes silent after eclipse, walk me through your fault tree), and evidence you have integrated real hardware, not just simulated it.'),
  ('Mission Operations Engineer', 'Sits on console commanding spacecraft: planning passes, catching anomalies, and making the real-time calls that keep missions alive.', 105000, 6, 'Bachelor''s degree (STEM)', ARRAY['Console operations & procedures', 'Anomaly response', 'Orbit/pass planning', 'Clear communication under pressure']::text[], '{"quadrant_a":0.5,"quadrant_b":0.93,"quadrant_c":0.3,"quadrant_d":0.15,"pace_preference":0.85,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '17-2011', 6.1, 134830, 4.5, 'approximate', 'Mapped to Aerospace Engineers (17-2011), verified batch-1 numbers; operations roles span engineering and technician codes.', 'The most accessible real space job: mission ops teams at NASA centers, Planet, Rocket Lab, and university ground stations hire strong STEM grads without aerospace degrees. Ground-station volunteering, amateur radio, and CubeSat ops experience all count directly.', 'Ops engineer in training certifies on console positions over 6-18 months, then flight controller, then anomaly lead or planning lead, then Flight Director-track roles running whole mission phases.', ARRAY['Procedure discipline (checklists, verification)', 'Spacecraft subsystem basics', 'Scripting for ops automation (Python)', 'Voice-loop communication protocol', 'Shift-work readiness']::text[], 'Mission control looks like constant drama; 95% of console time is quiet monitoring and planning, and the job is engineering the boring reliability that makes the dramatic saves unnecessary.', 'Simulation-style questions: telemetry shows battery voltage dropping during eclipse, what are your first three actions. They test procedure discipline, composure, and whether you communicate exactly what you know versus what you assume.'),
  ('Astronaut', 'Flies to space for a living: operating spacecraft, running experiments in microgravity, and doing spacewalks for NASA or commercial crews.', 152000, 4, 'Master''s in STEM + flight/operational experience', ARRAY['Operational judgment under pressure', 'Systems mastery', 'Physical & psychological resilience', 'Team performance in isolation']::text[], '{"quadrant_a":0.55,"quadrant_b":0.88,"quadrant_c":0.35,"quadrant_d":0.5,"pace_preference":0.8,"risk_tolerance":0.85}'::jsonb, '2025-09-01'::date, null, null, null, null, 'no_match', 'BLS has no astronaut category; pay shown reflects NASA civil-servant astronaut GS-scale ranges. Selection odds are extreme (NASA''s 2021 class took 10 of 12,000+ applicants) but every credential on the path is independently valuable.', 'NASA requires a STEM master''s plus either 2 years of professional experience or 1,000 pilot-in-command jet hours, then a selection gauntlet measured in years. Practically, people become astronauts by first becoming excellent at something else: test pilots, physicians, PhDs, military officers. Commercial crews (SpaceX private missions, Axiom) are opening a second, still-rare door.', 'Astronaut candidate training for 2 years, then mission support roles (CAPCOM, robotics) often for years before first flight assignment, then ISS or Artemis missions, then leadership roles in the astronaut office.', ARRAY['Deep excellence in one STEM/operational field first', 'Flying lessons or scuba certification (operational judgment)', 'Russian or expedition-style team experience', 'Physical fitness as a habit', 'Public communication']::text[], 'People treat it as a childhood-dream lottery ticket; the actual strategy is picking a career you would love even if selection never happens (test pilot, flight surgeon, planetary scientist), because that is literally what the selection board rewards.', 'NASA selection probes expedition behavior: how you performed in isolated, confined, high-consequence teams. Every technical credential is table stakes; the differentiator is evidence you are the person a crew wants beside them when things go wrong.'),
  ('Neurosurgeon', 'Operates on the brain and spine: tumors, aneurysms, trauma, and spinal reconstruction, in some of medicine''s longest and highest-stakes cases.', 600000, 4, 'MD + 7-year neurosurgery residency', ARRAY['Microsurgical technique', 'Neuroanatomy mastery', 'High-stakes decision making', 'Stamina & focus']::text[], '{"quadrant_a":0.6,"quadrant_b":0.93,"quadrant_c":0.2,"quadrant_d":0.2,"pace_preference":0.8,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '29-1249', 3.9, null, 0.6, 'close', 'Mapped to Surgeons, all other (29-1249), verified batch-1 numbers; BLS suppresses the median wage above its publication cap, and neurosurgery compensation surveys run far above even that cap.', 'The longest standard path in this catalog: top MCAT and grades into medical school, research productivity from year one (neurosurgery programs weigh publications heavily), honors in the surgery clerkship, then matching into one of about 120 US residency programs taking 1-4 residents each. The residency itself is 7 years.', '7-year residency with escalating operative responsibility, often a 1-2 year fellowship (spine, vascular, pediatric, tumor), then attending posts in academic or private practice, with full operative independence in your mid-30s.', ARRAY['Relentless study habits (anatomy, physiology)', 'Research skills: get into a lab early', 'Fine motor practice (suturing, microsurgery kits)', 'Stamina management', 'Team communication in the OR']::text[], 'The pay attracts people who underestimate the cost: 7+ years of 80-hour residency weeks after medical school, malpractice exposure, and cases that run 12 hours standing. The people who thrive genuinely love the operating itself.', 'Residency interviews probe research depth, ethical reasoning under scarcity (two emergent cases, one OR), and honest self-knowledge about why neurosurgery specifically, since every applicant is smart and every program knows the lifestyle math.'),
  ('Plastic Surgeon', 'Performs reconstructive and aesthetic surgery, from post-cancer breast reconstruction and hand trauma to elective cosmetic procedures.', 450000, 4, 'MD + 6-year plastic surgery residency', ARRAY['Surgical technique & aesthetics', 'Patient consultation', 'Tissue handling & grafting', 'Practice building']::text[], '{"quadrant_a":0.5,"quadrant_b":0.88,"quadrant_c":0.45,"quadrant_d":0.35,"pace_preference":0.6,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '29-1249', 3.9, null, 0.6, 'close', 'Mapped to Surgeons, all other (29-1249), verified batch-1 numbers; BLS suppresses the median wage above its publication cap.', 'One of the most competitive matches in medicine: integrated plastic surgery residencies take a handful of students per program, so research output, top board scores, and away rotations are near-mandatory. The alternative path is general surgery first, then a plastics fellowship.', '6-year integrated residency (or 5+3 via general surgery), optional aesthetic or microsurgery fellowship, then hospital-based reconstructive practice, private aesthetic practice, or a mix; private practice adds a real business-building phase.', ARRAY['Top-tier study habits for boards', 'Research and publication early', 'Suturing and tissue-handling practice', 'An artistic eye (drawing, sculpture genuinely help)', 'Communication and consultation skills']::text[], 'Outsiders equate it with cosmetic work; the specialty''s core is reconstruction (burns, cancer defects, congenital anomalies, hands), and many surgeons mix both. The aesthetic side is also a small business with marketing and payroll, not just an OR.', 'Programs probe aesthetic judgment (critique this outcome), manual evidence (what you have built or crafted), and maturity around elective-surgery ethics: managing patient expectations you cannot surgically meet.'),
  ('Ophthalmologist', 'Medical and surgical eye care: cataract and retina surgery, glaucoma management, and preserving the sense people fear losing most.', 320000, 4, 'MD + 4-year ophthalmology residency', ARRAY['Microsurgery', 'Diagnostic precision', 'Patient communication', 'Procedural volume management']::text[], '{"quadrant_a":0.55,"quadrant_b":0.9,"quadrant_c":0.35,"quadrant_d":0.15,"pace_preference":0.55,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '29-1241', 4, null, 0.5, 'approximate', 'Ophthalmologists (29-1241) is a new SOC in this batch: growth and openings are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2; median wage suppressed above BLS''s cap either way. Flagged for founder verification.', 'A competitive early match (ophthalmology runs its own match a year early): strong scores, research in the field, and letters from academic ophthalmologists. The microsurgical skills assessment matters; programs want steady hands and calm temperament.', '4-year residency, optional 1-2 year fellowship (retina, cornea, glaucoma, pediatric), then practice; cataract surgery volume is the economic engine of most private practices.', ARRAY['Pre-med excellence plus research', 'Fine motor practice under magnification', 'Optics fundamentals', 'Efficient clinical exam skills', 'Empathy for anxious patients']::text[], 'People lump it with optometry; ophthalmologists are surgeons who spend years mastering procedures measured in microns. It is also one of the better lifestyle surgical fields, which is exactly why it is so competitive.', 'Expect optics and neuro-ophthalmology questions, manual dexterity evidence, and probing of why eyes: programs filter for people drawn to precision and longitudinal patient relationships, not just the lifestyle.'),
  ('OB/GYN Physician', 'Delivers babies and provides the full arc of women''s health care, from routine gynecology to high-risk pregnancies and surgery.', 270000, 3, 'MD + 4-year OB/GYN residency', ARRAY['Surgical & procedural skill', 'Longitudinal patient relationships', 'Crisis management (L&D)', 'Counseling & communication']::text[], '{"quadrant_a":0.35,"quadrant_b":0.6,"quadrant_c":0.87,"quadrant_d":0.2,"pace_preference":0.75,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '29-1218', 3, null, 0.7, 'approximate', 'Obstetricians and Gynecologists (29-1218) is a new SOC in this batch: growth and openings are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2; median wage suppressed above BLS''s cap. Flagged for founder verification.', 'A standard competitive match: strong clerkship performance in OB/GYN, letters from the field, and demonstrated commitment to women''s health. Residency mixes surgery, obstetrics, and clinic from day one.', '4-year residency, optional fellowship (maternal-fetal medicine, REI/fertility, gyn-oncology, urogynecology), then hospital-employed or private practice; many later shift toward office gynecology as call burden ages poorly.', ARRAY['Pre-med fundamentals', 'Comfort with both clinic and OR', 'Communication in emotionally loaded moments', 'Stamina for overnight call', 'Advocacy and counseling skills']::text[], 'People underestimate the surgical breadth (hysterectomies, c-sections, oncology-adjacent procedures) and the call intensity: babies arrive at 3 AM for your whole career unless you subspecialize away from obstetrics.', 'Programs probe composure in emergencies (shoulder dystocia, hemorrhage), ethical reasoning in reproductive care, and whether you genuinely want the 3 AM delivery life or are romanticizing it.'),
  ('Nurse Anesthetist (CRNA)', 'Administers anesthesia independently for surgeries and procedures, one of the highest-paid and most autonomous nursing roles in existence.', 212000, 10, 'BSN + ICU experience + 3-year DNP/DNAP', ARRAY['Anesthesia pharmacology', 'Airway management', 'Hemodynamic monitoring', 'Crisis response']::text[], '{"quadrant_a":0.5,"quadrant_b":0.92,"quadrant_c":0.35,"quadrant_d":0.1,"pace_preference":0.75,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '29-1151', 10, 212650, 2.5, 'approximate', 'Nurse Anesthetists (29-1151) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'The defined ladder is its strength: BSN, then 1-3 years in a high-acuity ICU (this is a hard requirement), then a 3-year doctoral CRNA program. Admissions are competitive on ICU quality, GPA, and the GRE/CCRN; shadowing a CRNA is effectively expected.', 'ICU nurse to CRNA program to staff CRNA; from there independent practice (full autonomy in many states), locum work at premium rates, or chief CRNA and program faculty roles.', ARRAY['BSN with strong science grades', 'High-acuity ICU experience (CVICU/SICU preferred)', 'CCRN certification', 'Pharmacology depth', 'Calm structured crisis thinking']::text[], 'People assume anesthesiologists supervise everything; in many states CRNAs practice fully independently, and they personally deliver most anesthesia in rural America. The autonomy and pay are real, and so is the sole-responsibility weight.', 'Programs and employers probe ICU judgment (walk through managing a crashing patient), pharmacology recall, and composure: the entire job is quiet vigilance punctuated by 90 seconds where you must be perfect.'),
  ('Optometrist', 'Primary eye care: exams, prescriptions, disease detection, and managing conditions like glaucoma, with predictable hours and your own practice as a real option.', 132000, 8, 'Doctor of Optometry (4 years post-bachelor''s)', ARRAY['Clinical examination', 'Optics & refraction', 'Patient education', 'Practice management']::text[], '{"quadrant_a":0.45,"quadrant_b":0.86,"quadrant_c":0.5,"quadrant_d":0.15,"pace_preference":0.4,"risk_tolerance":0.2}'::jsonb, '2025-09-01'::date, '29-1041', 8, 131860, 1.9, 'approximate', 'Optometrists (29-1041) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'A contained, predictable path: pre-med-style undergrad, the OAT exam, then 4 years of optometry school (about 25 US programs). Far less brutal than the MD route while still granting doctoral autonomy and prescribing rights.', 'Associate at a private or retail-affiliated practice, then partner or practice owner; ownership is where incomes climb well past the median. Residency-trained ODs subspecialize in ocular disease, pediatrics, or vision therapy.', ARRAY['Strong biology/physics foundation', 'OAT preparation', 'People skills for all-day patient flow', 'Business basics if ownership appeals', 'Attention to systematic detail']::text[], 'Dismissed as ''glasses prescriptions''; ODs now manage real ocular disease, catch diabetes and hypertension before anyone else, and in a growing number of states perform minor procedures. It is one of healthcare''s best lifestyle-to-income ratios.', 'Optometry programs weigh empathy and communication as much as science; be ready to explain a complex idea simply, and to show you have shadowed enough to know what a Tuesday actually looks like.'),
  ('Physician-Scientist (MD-PhD)', 'Splits life between treating patients and running a research lab, translating discoveries into treatments as faculty at academic medical centers.', 220000, 8, 'MD-PhD (8 years) + residency/fellowship', ARRAY['Research design & grant writing', 'Clinical practice', 'Scientific writing', 'Lab leadership']::text[], '{"quadrant_a":0.92,"quadrant_b":0.5,"quadrant_c":0.3,"quadrant_d":0.5,"pace_preference":0.45,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'approximate', 'Mapped to Medical Scientists (19-1042), verified batch-1 numbers; actual MD-PhD faculty compensation blends clinical pay well above that research-scientist median.', 'MSTP programs (about 50, NIH-funded, tuition-free with stipend) take research-heavy applicants: multiple years of lab work, ideally a publication, plus MD-level stats. The application essentially asks you to prove you already think like a scientist.', '8 years MD-PhD, then residency and fellowship chosen for research compatibility, then assistant professor juggling a K-award, clinic time, and building a lab, with the R01 grant as the make-or-break milestone toward tenure.', ARRAY['Sustained undergrad research (2+ years in one lab)', 'Scientific writing', 'Statistics and experimental design', 'Clinical shadowing to confirm the MD half', 'Grit for a 15-year training arc']::text[], 'The free tuition draws applicants who underestimate the arc: you finish training in your mid-30s and then face the hardest part, winning grants. The people who thrive would run experiments even if unpaid.', 'MSTP interviews dissect your research: hypotheses, controls, what failed, what you would do next. They probe whether the clinical motivation is real or decorative, since the dual identity only works if both halves are genuine.'),
  ('Neuroscientist', 'Studies how brains compute, remember, and break, from single neurons to behavior, in academic, biotech, and neurotech labs.', 105000, 9, 'PhD in neuroscience or related', ARRAY['Experimental design', 'Data analysis (Python/R)', 'Electrophysiology or imaging', 'Scientific writing']::text[], '{"quadrant_a":0.9,"quadrant_b":0.45,"quadrant_c":0.2,"quadrant_d":0.45,"pace_preference":0.35,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '19-1042', 8.7, 100590, 9.6, 'close', 'Mapped to Medical Scientists (19-1042), verified batch-1 numbers; neuroscience research sits within this category.', 'Join a lab as an undergrad and stay long enough to own a project; PhD admissions weigh sustained research and letters above grades. Neurotech companies (Neuralink-style BCI, pharma neuro divisions) increasingly hire straight from PhD without a postdoc.', 'PhD (5-6 years), then either academic postdoc toward faculty, or industry scientist in biotech/neurotech where computational skills command premiums; data-heavy neuroscientists also cross into ML research.', ARRAY['Python for data analysis', 'Statistics done properly', 'One wet-lab or recording technique deeply', 'Scientific reading habits', 'Clear writing']::text[], 'Pop neuroscience oversells brain scans; real work is slow, statistical, and narrow. The compensation ceiling in academia is modest, which is why the industry and neurotech paths matter to know about early.', 'Expect deep probing of your research contribution (what was YOUR idea), statistics fluency, and for industry roles, whether you can translate open-ended science into milestone-driven projects.'),
  ('Quantum Computing Researcher', 'Develops the algorithms, error correction, and hardware control that inch quantum computers toward useful, at labs like IBM, Google, and IonQ.', 150000, 18, 'PhD (physics, CS, or EE) typical', ARRAY['Quantum mechanics & information theory', 'Linear algebra mastery', 'Python/Qiskit/Cirq', 'Research publication']::text[], '{"quadrant_a":0.95,"quadrant_b":0.35,"quadrant_c":0.1,"quadrant_d":0.5,"pace_preference":0.35,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '15-1221', 19.7, 140910, 3.2, 'approximate', 'Mapped to Computer and Information Research Scientists (15-1221), verified batch-1 numbers; quantum research spans this and physicist codes.', 'Take quantum information courses early (many are free: Qiskit textbook, MIT OCW), contribute to open-source quantum software, and target research internships at IBM Quantum, Google Quantum AI, or national labs. Most research roles want a PhD, but quantum software engineering hires strong masters-level coders.', 'PhD in a quantum group, then research scientist at a hardware company or national lab, then technical lead of an error-correction or algorithms team; the field is small enough that strong contributors get visible fast.', ARRAY['Linear algebra to fluency', 'Quantum mechanics fundamentals', 'Python plus Qiskit or Cirq', 'One publishable or open-source project', 'Classical algorithms and complexity']::text[], 'Hype suggests quantum will replace classical computing; researchers spend their days fighting decoherence and error rates on machines that cannot yet beat a laptop at most tasks. The bet is on the decade, not the demo.', 'Whiteboard quantum information questions (why does the no-cloning theorem matter for error correction), linear algebra fluency, and honest calibration about what current hardware can and cannot do.'),
  ('Research Mathematician', 'Proves new theorems and builds the mathematical machinery other fields run on, in academia, national security, and research labs.', 116000, 3, 'PhD in mathematics', ARRAY['Proof & abstraction', 'Deep sustained focus', 'Mathematical writing', 'Collaboration across fields']::text[], '{"quadrant_a":0.96,"quadrant_b":0.35,"quadrant_c":0.1,"quadrant_d":0.4,"pace_preference":0.3,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '15-2021', 3, 116440, 0.2, 'approximate', 'Mathematicians (15-2021) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Math competitions and undergrad research (REUs) signal early; PhD admissions rest on advanced coursework and letters. The NSA is the country''s largest employer of mathematicians, and quant finance and tech research labs recruit the same PhDs at multiples of academic pay.', 'PhD (5-6 years), then academic postdocs toward scarce tenure-track lines, or direct entry to NSA/IDA, national labs, or quant funds; many split careers between proving theorems and applying them.', ARRAY['Proof-based coursework as early as possible', 'Real analysis and abstract algebra', 'LaTeX and mathematical writing', 'One REU or research experience', 'Programming (increasingly expected)']::text[], 'People picture solitary genius; modern math is collaborative and the academic market is brutally tight. Knowing the NSA/quant/lab exits exist changes the risk calculus entirely, the PhD is not a one-door bet.', 'Academic hiring runs on the research statement and letters; industry math roles (NSA, quant) test problem-solving live: expect to prove small things on a whiteboard and to explain your thesis to a smart non-specialist.'),
  ('Climate Scientist', 'Models how the climate system behaves and what comes next, informing everything from IPCC reports to how insurers price risk.', 97000, 5, 'PhD typical (MS for applied roles)', ARRAY['Climate modeling', 'Statistical analysis', 'Scientific computing (Python)', 'Science communication']::text[], '{"quadrant_a":0.88,"quadrant_b":0.4,"quadrant_c":0.3,"quadrant_d":0.5,"pace_preference":0.35,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '19-2021', 5, 95380, 0.8, 'approximate', 'Atmospheric and Space Scientists (19-2021) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Earth science or physics undergrad with heavy programming, then research with a modeling group; NOAA, NASA, and NCAR internships are the classic doors. A fast-growing private market (climate risk analytics, insurance, energy) hires MS-level scientists at premiums.', 'PhD then postdoc toward federal lab or faculty positions, or MS then climate-risk analyst at insurers, banks, and startups where demand currently outruns supply.', ARRAY['Python and scientific computing', 'Statistics and time-series analysis', 'Atmospheric physics fundamentals', 'GIS and geospatial data', 'Writing for non-scientists']::text[], 'Assumed to be advocacy; the day job is debugging model code and quantifying uncertainty. The private-sector arm (catastrophe modeling, climate risk) is where hiring is hottest and pay beats academia.', 'Expect probing of statistical rigor (how do you separate signal from natural variability), coding fluency, and the ability to state uncertainty honestly without dissolving into ''we cannot know anything.'''),
  ('National Lab Research Scientist', 'Runs experiments at the government''s flagship labs (Los Alamos, Lawrence Livermore, Oak Ridge, Argonne) on fusion, materials, supercomputing, and security.', 160000, 4, 'PhD in physical science or engineering', ARRAY['Experimental or computational research', 'Grant/program funding navigation', 'Interdisciplinary collaboration', 'Security-clearance readiness']::text[], '{"quadrant_a":0.93,"quadrant_b":0.5,"quadrant_c":0.2,"quadrant_d":0.4,"pace_preference":0.35,"risk_tolerance":0.35}'::jsonb, '2025-09-01'::date, '19-2012', 4, 166290, 1.7, 'close', 'Mapped to Physicists (19-2012), verified batch-1 numbers; national-lab scientists span physicist and adjacent research codes.', 'The labs run enormous student pipelines: SULI internships for undergrads, graduate fellowships (like the DOE CSGF), and postdoc programs that convert heavily to staff. US citizenship materially widens options at the weapons labs due to clearances.', 'Postdoc to staff scientist, then principal investigator on lab-directed research funds, then group leader or program manager steering multi-million-dollar research directions.', ARRAY['A physical-science PhD trajectory', 'Scientific computing (the labs run the country''s biggest supercomputers)', 'One SULI or lab internship', 'Team-based research habits', 'Clear technical writing']::text[], 'Seen as slower-paced academia; labs offer academia''s intellectual freedom with industrial resources and no teaching load, at pay well above universities. The tradeoff is mission-directed research and, at some labs, classified work you can never publish.', 'Panels probe research depth plus mission fit: can your skills serve programs from fusion to stockpile stewardship. Expect a research talk and questions about working on team-scale, deadline-driven science.'),
  ('Think Tank Policy Researcher', 'Turns rigorous analysis into policy influence at places like Brookings, RAND, and CSIS, shaping how governments actually decide.', 120000, 3, 'Master''s/PhD (policy, economics, IR)', ARRAY['Policy analysis & writing', 'Quantitative methods', 'Stakeholder engagement', 'Public communication']::text[], '{"quadrant_a":0.87,"quadrant_b":0.35,"quadrant_c":0.45,"quadrant_d":0.5,"pace_preference":0.45,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '19-3094', 3, 132350, 0.6, 'approximate', 'Political Scientists (19-3094) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Research assistant posts at think tanks hire sharp bachelors-level quants who can write; that RA period plus a policy-relevant masters or PhD is the standard ladder. Publishing anything rigorous under your own name early, even a data-driven blog, genuinely moves applications.', 'RA to research associate to fellow, with government stints (Hill staff, agency roles) interleaved; senior fellows effectively run small research businesses fundraising for their own agendas.', ARRAY['Statistics and causal inference', 'Writing that non-academics finish', 'One policy domain deeply', 'Networking across ideological lines', 'Public speaking']::text[], 'Imagined as punditry; the credible institutions live on methodological rigor, and researchers spend far more time on data and drafts than on television. Influence is measured in staffer briefings, not retweets.', 'Writing samples carry the application. Interviews probe analytical honesty (what would change your mind), speed from question to structured answer, and whether you can brief a hostile audience without flinching.'),
  ('Semiconductor Chip Design Engineer', 'Designs the processors and custom silicon underneath the AI boom, at NVIDIA, Apple, AMD, TSMC, and a wave of chip startups.', 155000, 7, 'Bachelor''s/Master''s (EE/CE)', ARRAY['Digital logic & RTL design (Verilog)', 'Computer architecture', 'Verification & debug', 'Physical design awareness']::text[], '{"quadrant_a":0.91,"quadrant_b":0.6,"quadrant_c":0.1,"quadrant_d":0.3,"pace_preference":0.45,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '17-2061', 7, 155020, 5.1, 'approximate', 'Computer Hardware Engineers (17-2061) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Computer architecture and digital design courses plus a Verilog project you can defend (build a RISC-V core, it is the standard flex) get internships at NVIDIA, Apple silicon, AMD, and Qualcomm. The CHIPS Act era has fabs and design houses hiring aggressively; masters degrees help but strong RTL portfolios break in at bachelors level.', 'Design or verification engineer on one block for 2-3 years, then block owner, then microarchitect defining what gets built, then principal engineer or architecture lead on a chip generation.', ARRAY['Digital logic and Verilog/SystemVerilog', 'Computer architecture (build a toy CPU)', 'C/C++ and scripting', 'Verification concepts (UVM basics)', 'Linux command-line fluency']::text[], 'Software''s shadow hides that chip engineers at top firms now match or beat software pay, with better job security through the AI hardware cycle. Verification (testing designs) is over half the jobs and the classic entry door people overlook.', 'Whiteboard logic design (build a FIFO, cross clock domains safely), architecture reasoning (what limits single-thread performance), and debug scenarios; they want people who think in gates and pipelines, not just code.'),
  ('AI Safety Researcher', 'Works on making frontier AI systems honest, controllable, and aligned, at labs like Anthropic, OpenAI, DeepMind, and academic institutes.', 160000, 18, 'MS/PhD common, exceptional portfolios break in', ARRAY['Deep learning research', 'Interpretability or alignment methods', 'Mathematical maturity', 'Research communication']::text[], '{"quadrant_a":0.9,"quadrant_b":0.35,"quadrant_c":0.25,"quadrant_d":0.55,"pace_preference":0.45,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '15-1221', 19.7, 140910, 3.2, 'approximate', 'Mapped to Computer and Information Research Scientists (15-1221), verified batch-1 numbers; frontier-lab compensation runs well above this category median.', 'The field hires on demonstrated research ability more than credentials: replicate interpretability papers, publish thoughtful analysis, and apply to programs built as pipelines (MATS, Anthropic and DeepMind residencies). Strong ML engineering plus genuine safety motivation beats a generic PhD.', 'Research engineer or resident, then research scientist owning an agenda (interpretability, evaluations, alignment training methods), then team lead shaping a lab''s safety strategy.', ARRAY['Deep learning fundamentals (build transformers from scratch)', 'PyTorch fluency', 'Linear algebra and probability', 'Reproducing papers end-to-end', 'Writing up findings clearly']::text[], 'Seen as philosophy; day-to-day it is empirical ML research with experiments, ablations, and code review. The scarce skill is asking the right question about a model and designing the experiment that answers it.', 'Research interviews probe how you think about open problems (how would you test whether a model is deceptive), ML fundamentals under a whiteboard, and evidence you finish hard self-directed projects.'),
  ('Engineering Manager', 'Leads engineering teams: hiring, unblocking, and multiplying other engineers while owning delivery of real systems.', 168000, 6, 'Bachelor''s + senior engineering experience', ARRAY['Technical leadership', 'Coaching & feedback', 'Project delivery', 'Cross-functional communication']::text[], '{"quadrant_a":0.55,"quadrant_b":0.55,"quadrant_c":0.86,"quadrant_d":0.35,"pace_preference":0.65,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '11-9041', 6, 167740, 14, 'approximate', 'Architectural and Engineering Managers (11-9041) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Not an entry job, but a track to aim at: become a senior engineer people already come to for help, then take a tech-lead role, then a team. The transition is offered to engineers who make everyone around them better, and it is reversible at good companies.', 'Senior engineer to tech lead to engineering manager (5-8 people), then senior EM or director of multiple teams, then VP of engineering; compensation scales with organizational scope.', ARRAY['Genuine engineering depth first', 'Mentoring juniors deliberately', 'Writing clearly (docs, feedback, strategy)', 'Running meetings that end with decisions', 'Estimating and delivering projects']::text[], 'Treated as the default promotion; it is a career change into a people-outcomes job where your output becomes indirect. Engineers who take it for the title without wanting the people work are the unhappy managers everyone has had.', 'Behavioral depth on real situations: the underperformer you coached or exited, the deadline you renegotiated, the conflict between your best engineers. Plus enough system design to prove you still earn technical respect.'),
  ('Quantitative Developer', 'Builds the low-latency systems and research infrastructure that trading firms'' strategies run on, where engineering rigor directly prints money.', 170000, 15, 'Bachelor''s/Master''s (CS, math)', ARRAY['C++ performance engineering', 'Python research tooling', 'Systems & networking', 'Numerical methods']::text[], '{"quadrant_a":0.94,"quadrant_b":0.5,"quadrant_c":0.1,"quadrant_d":0.3,"pace_preference":0.8,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'close', 'Mapped to Software Developers (15-1252), verified batch-1 numbers; quant-firm compensation runs far above the category median.', 'Trading firms (Jane Street, Citadel, HRT, Jump) recruit through competitive programming performance, hard technical interviews, and internships that pay like full-time jobs. Strong C++ plus algorithmic problem-solving is the profile; finance knowledge is explicitly not required at entry.', 'Quant dev on one system (market data, execution, research platform) for 2-3 years, then owning trading-critical infrastructure, then team lead; total compensation escalates faster than almost any other engineering track.', ARRAY['C++ including memory and cache behavior', 'Data structures and algorithms to competition level', 'Linux systems programming', 'Python for tooling', 'Probability puzzles (interview staple)']::text[], 'Confused with quant researchers; devs build the weapons rather than aim them, and at top firms the pay gap between the two roles is smaller than outsiders assume. The work is closer to high-performance systems engineering than to finance.', 'Multiple rounds of hard algorithms and C++ internals (what does the cache do to this loop), probability brainteasers, and systems design under latency budgets measured in microseconds.'),
  ('Embedded Systems Engineer', 'Writes the software inside physical things: cars, medical devices, rockets, robots, where code meets voltage and failure is not an option.', 125000, 8, 'Bachelor''s (CE/EE/CS)', ARRAY['C/C++ on microcontrollers', 'RTOS & concurrency', 'Hardware debugging (scopes, logic analyzers)', 'Communication protocols (SPI/I2C/CAN)']::text[], '{"quadrant_a":0.88,"quadrant_b":0.65,"quadrant_c":0.1,"quadrant_d":0.25,"pace_preference":0.5,"risk_tolerance":0.3}'::jsonb, '2025-09-01'::date, '15-1252', 15.8, 133080, 115.2, 'close', 'Mapped to Software Developers (15-1252), verified batch-1 numbers; embedded work also overlaps hardware-engineer codes.', 'Build things that blink, sense, and move: an STM32 or ESP32 project portfolio outweighs coursework. Automotive, aerospace, medical devices, and robotics all chronically under-hire for embedded relative to demand, making it one of the least crowded doors in software.', 'Firmware engineer on one board or subsystem, then platform owner, then embedded architect defining hardware-software boundaries across products.', ARRAY['C with pointers to fluency', 'One microcontroller family hands-on', 'Reading datasheets and schematics', 'RTOS concepts (FreeRTOS)', 'Debugging with real instruments']::text[], 'Treated as low-level drudgery; embedded engineers are the ones whose code flies planes and paces hearts, with job security that web frameworks never provide. Fewer bootcamp grads compete here, seniors are scarce and priced accordingly.', 'Expect C minutiae (volatile, interrupts, memory-mapped registers), concurrency reasoning without an OS safety net, and debugging stories where the bug turned out to be hardware.'),
  ('Air Traffic Controller', 'Directs aircraft through crowded skies in real time, one of the highest-paying careers with no degree requirement in America.', 144000, 2, 'FAA Academy (no degree required, age limit 30)', ARRAY['Spatial reasoning under load', 'Instant prioritization', 'Precise phraseology', 'Sustained vigilance']::text[], '{"quadrant_a":0.45,"quadrant_b":0.95,"quadrant_c":0.3,"quadrant_d":0.1,"pace_preference":0.95,"risk_tolerance":0.25}'::jsonb, '2025-09-01'::date, '53-2021', 2, 144580, 2.2, 'approximate', 'Air Traffic Controllers (53-2021) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Apply to the FAA''s periodic open announcements before age 31, pass the ATSA aptitude test (spatial and multitasking, the Skill Lab games are genuinely close cousins), then the FAA Academy in Oklahoma City, where washout is real. CTI college programs offer a parallel door.', 'Academy to developmental controller at an assigned facility, certifying position-by-position over 2-3 years, then full performance controller; pay scales with facility traffic, with the busiest towers and centers well above $200k.', ARRAY['Spatial and multitasking games (seriously)', 'The ATSA test format', 'Aviation phraseology basics', 'Sleep discipline for shift work', 'Calm under simulated overload']::text[], 'People assume a degree is required; it is one of the only six-figure federal careers open at 18 with none. The real barriers are the age cutoff, the aptitude test, and the training washout rate, not credentials.', 'Selection is test-driven rather than interview-driven: the ATSA measures exactly the reflex, sequencing, and spatial skills this assessment''s Skill Lab measures, plus a rigorous medical and background check.'),
  ('FBI Special Agent', 'Investigates federal crimes from counterterrorism to cybercrime, carrying a badge, a caseload, and a security clearance.', 97000, 2, 'Bachelor''s + 2 years work experience (age 23-36)', ARRAY['Investigation & interviewing', 'Report writing', 'Judgment under ambiguity', 'Physical readiness']::text[], '{"quadrant_a":0.5,"quadrant_b":0.87,"quadrant_c":0.5,"quadrant_d":0.3,"pace_preference":0.7,"risk_tolerance":0.6}'::jsonb, '2025-09-01'::date, '33-3021', 2, 91100, 8.5, 'approximate', 'Detectives and Criminal Investigators (33-3021) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'The FBI hires specialists, not generalists: accountants, lawyers, cyber experts, linguists, and veterans, all with a bachelor''s plus two years of real work. The process (application, fitness test, polygraph, background) takes a year or more; the accounting and cyber entry programs are the most undersubscribed doors.', 'Quantico''s 19-week academy, then a field office assignment you do not choose, then squad specialization (violent crime, counterintelligence, cyber), then supervisory special agent or headquarters program roles.', ARRAY['A marketable specialty first (accounting, CS, law, languages)', 'Physical fitness to FBI PFT standards', 'Clean digital and financial history', 'Writing precise reports', 'Interview and rapport skills']::text[], 'TV suggests daily raids; most agent work is methodical investigation, subpoenas, and interviews, and your first office is wherever the Bureau needs you. The specialty-first path surprises people: the FBI wants your accounting degree more than your criminology one.', 'Structured behavioral interviews score judgment, integrity, and composure against fixed anchors; the polygraph and background investigation examine your actual life, which is the part applicants underestimate.'),
  ('Intelligence Analyst', 'Pieces together fragmentary information into assessments that guide national decisions, at agencies like CIA, NSA, and DIA.', 95000, 3, 'Bachelor''s (IR, regional studies, STEM all work)', ARRAY['Analytic tradecraft', 'Writing under uncertainty', 'Regional or technical expertise', 'Briefing']::text[], '{"quadrant_a":0.89,"quadrant_b":0.55,"quadrant_c":0.2,"quadrant_d":0.35,"pace_preference":0.6,"risk_tolerance":0.4}'::jsonb, '2025-09-01'::date, '33-3021', 2, 91100, 8.5, 'approximate', 'No clean BLS category for intelligence analysts; mapped loosely to Detectives and Criminal Investigators (33-3021), a new SOC in this batch, best-effort values flagged for founder verification.', 'Apply directly to agency websites (the process includes clearance investigation measured in months to a year), or enter via military intelligence, which remains the largest pipeline. Language skills, STEM depth, or genuine regional expertise move applications; so do the agencies'' undergraduate internship programs, which convert heavily.', 'Junior analyst on one account (a country, a network, a technology), then senior analyst briefing policymakers, then branch chief or a rotation to the National Security Council; private-sector intelligence and geopolitical risk firms poach cleared analysts at premiums.', ARRAY['Writing short, structured, caveated assessments', 'A hard language (Mandarin, Russian, Arabic, Farsi)', 'Statistics and structured analytic techniques', 'A clean, clearable personal history', 'Deep reading on one region or domain']::text[], 'Confused with operations officers; analysts are the writers and thinkers, not the recruiters of sources. The work is closer to investigative journalism with classified sources than to anything cinematic.', 'Analytic exercises: here is fragmentary reporting, write the assessment and defend your confidence levels. They probe intellectual honesty (distinguishing what you know from what you infer) above ideology or bravado.'),
  ('Corporate Strategy Manager', 'Runs the internal consulting team that decides what a company builds, buys, and kills next, reporting into the C-suite.', 135000, 8, 'Bachelor''s + consulting/banking experience typical', ARRAY['Strategic analysis', 'Financial modeling', 'Executive communication', 'Cross-functional influence']::text[], '{"quadrant_a":0.88,"quadrant_b":0.4,"quadrant_c":0.45,"quadrant_d":0.5,"pace_preference":0.6,"risk_tolerance":0.45}'::jsonb, '2025-09-01'::date, '13-1111', 8.8, 101190, 98.1, 'close', 'Mapped to Management Analysts (13-1111), verified batch-1 numbers; corporate strategy sits within this category.', 'The standard door is 2-3 years at a consulting firm or bank, then an in-house strategy team; the rarer direct door is a rotational program (many F500s run strategy or CEO-track rotations for top grads). Internal transfers from finance or ops teams who show strategic chops also land here.', 'Senior analyst to manager owning a workstream, then director running the annual strategy cycle, then VP of strategy or a pivot into general management as a business-unit leader, the classic path to P&L ownership.', ARRAY['Financial modeling and valuation', 'Slide-writing that executives actually read', 'Market sizing and competitive analysis', 'Interviewing stakeholders efficiently', 'Running a meeting of people senior to you']::text[], 'Sounds like abstract thinking; the job is mostly building the fact base that forces a decision, then herding executives toward it. Influence without authority is the entire skill.', 'Case interviews persist post-consulting: size this market, should we enter it. Plus behavioral probing of whether you can push back on senior leaders without getting fired, diplomatically.'),
  ('Sales Engineer', 'The technical half of enterprise sales: proving to skeptical engineers that the product actually works, and getting paid on the deal when it closes.', 118000, 6, 'Bachelor''s (engineering/CS common)', ARRAY['Technical demos & POCs', 'Discovery questioning', 'Solution architecture', 'Commercial instinct']::text[], '{"quadrant_a":0.55,"quadrant_b":0.35,"quadrant_c":0.88,"quadrant_d":0.4,"pace_preference":0.7,"risk_tolerance":0.5}'::jsonb, '2025-09-01'::date, '41-9031', 6, 116950, 5.2, 'approximate', 'Sales Engineers (41-9031) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Two doors: engineers who discover they like explaining more than building, and technical support or implementation staff who step toward revenue. SaaS companies hire SE interns and associates directly now; a demo you built plus the ability to whiteboard an architecture live is the interview.', 'Associate SE to SE owning a patch of accounts, then senior/principal SE on the largest deals, then SE leadership or a pivot to product management; on-target earnings scale with the sales team''s success.', ARRAY['Enough coding to build real demos', 'Public speaking and whiteboarding', 'Discovery: asking before pitching', 'One product domain deeply (data, security, cloud)', 'Objection handling']::text[], 'Engineers dismiss it as sales; SEs keep their technical identity, skip the cold-calling, and often out-earn the developers who build the product, with commission upside on top of solid bases.', 'The demo panel is the real test: present a product to a room playing hostile buyers, recover from a planted failure, and handle the ''that competitor is cheaper'' objection without trashing anyone.'),
  ('Industrial Designer', 'Designs the physical products people hold: consumer electronics, furniture, vehicles, and medical devices, where form meets manufacturing.', 76000, 3, 'Bachelor''s in industrial design', ARRAY['Sketching & form development', 'CAD (Rhino, SolidWorks)', 'Prototyping', 'Design for manufacturing']::text[], '{"quadrant_a":0.35,"quadrant_b":0.3,"quadrant_c":0.35,"quadrant_d":0.9,"pace_preference":0.5,"risk_tolerance":0.55}'::jsonb, '2025-09-01'::date, '27-1021', 3, 76250, 2.3, 'approximate', 'Industrial Designers (27-1021) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Portfolio is everything: an ID degree from a program with strong shop culture, plus internships at consultancies or corporate design studios (Apple, Whoop, IDEO-style firms). Process documentation, showing how you think from sketch to prototype, beats pretty renders.', 'Junior designer executing others'' directions, then designer owning products, then senior/lead defining design language, then design director; the ceiling rises sharply at design-led companies.', ARRAY['Sketching daily (it is a thinking tool)', 'Rhino or SolidWorks', 'Physical prototyping (3D print, foam, wood)', 'Photography for portfolio', 'Manufacturing processes literacy']::text[], 'Seen as art; industrial design is constraint negotiation between users, engineering, and factories, and designers who understand injection molding get hired over ones with prettier portfolios.', 'Portfolio walkthroughs probing process (what did you reject and why), a design exercise with awkward constraints, and whether you take critique as information rather than injury.'),
  ('Fashion Designer', 'Creates apparel collections from concept to production, in houses, brands, and increasingly through direct-to-consumer labels of one''s own.', 79000, 1, 'Bachelor''s (fashion design) or portfolio equivalent', ARRAY['Garment construction & patternmaking', 'Collection development', 'Textile knowledge', 'Trend synthesis']::text[], '{"quadrant_a":0.15,"quadrant_b":0.3,"quadrant_c":0.4,"quadrant_d":0.92,"pace_preference":0.6,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '27-1022', 1, 79290, 2.4, 'approximate', 'Fashion Designers (27-1022) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2. Flagged for founder verification.', 'Learn construction for real (sewing and patternmaking separate designers from sketchers), build a small cohesive collection, and take any assistant role inside the industry; the famous schools (FIT, Parsons, CSM) are networks as much as educations. Social-media-native labels are a legitimate parallel door.', 'Design assistant executing tech packs, then associate designer owning a category, then designer/senior designer, then design director; the entrepreneurial fork (your own label) can start at any rung and dominates the upside.', ARRAY['Sewing and garment construction', 'Patternmaking basics', 'Adobe Illustrator tech packs', 'Textile fundamentals', 'A tightly edited 10-look portfolio']::text[], 'Project Runway myths hide a production job: measurements, fittings, factory emails, and margins. The winners love clothes as engineered objects, not just as images.', 'Portfolio review probing construction knowledge (how would you actually make this), speed exercises (sketch a capsule for this brand by tomorrow), and culture fit with the house''s aesthetic.'),
  ('Screenwriter', 'Writes the scripts films and series are built from, a swing-for-the-fences creative career with real, if brutal, professional ladders.', 74000, 4, 'No degree required; craft and contacts', ARRAY['Story structure', 'Dialogue', 'Rewriting on notes', 'Pitching']::text[], '{"quadrant_a":0.25,"quadrant_b":0.3,"quadrant_c":0.35,"quadrant_d":0.93,"pace_preference":0.4,"risk_tolerance":0.7}'::jsonb, '2025-09-01'::date, '27-3043', 4, 73690, 15.2, 'approximate', 'Writers and Authors (27-3043) is a new SOC in this batch: values are best-effort from the same BLS 2024-34 cycle but not yet re-verified against Table 1.2; screenwriting income is extremely variable around any median. Flagged for founder verification.', 'Write several complete scripts (the first ones are practice), place in the few contests that matter (Nicholl, Austin), and get staffed via writers'' rooms, assistant jobs that feed them (writers'' PA, showrunner''s assistant), or fellowship programs at networks. Los Angeles proximity still matters for television.', 'Staff writer to story editor to producer-level writer across seasons, or feature route via spec sales and assignments; showrunning is the executive track where writers become the CEO of a series.', ARRAY['Finish scripts, plural (structure is learned by completing)', 'Read produced screenplays constantly', 'Give and take notes without ego', 'Loglines and pitching', 'A survival income plan for the early years']::text[], 'People polish one screenplay for years; working writers generate constantly and treat notes as the job, not an insult. The WGA minimums are solid money, the variance in getting there is the hard part, and this catalog says so plainly.', 'Staffing meetings are vibe-and-voice interviews: can you pitch your take on their show, take a note live, and be someone a room wants around at hour ten. The script sample does the technical arguing for you.');
